<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientBackchannelClientNotificationEndpointAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientBackchannelClientNotificationEndpointAccessor trait.
 *
 * Covers null default, string/VO assignment via withBackchannelClientNotificationEndpoint,
 * getBackchannelClientNotificationEndpoint/backchannelClientNotificationEndpoint accessors, and isBackchannelClientNotificationEndpointChanged with/without original.
 */
class TrustedClientBackchannelClientNotificationEndpointAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withBackchannelClientNotificationEndpoint creates a new instance with the BackchannelClientNotificationEndpoint set
     * from a string value, and getBackchannelClientNotificationEndpoint returns the primitive string.
     */
    public function testWithBackchannelClientNotificationEndpointFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientBackchannelClientNotificationEndpointAccessorUnitTest();

        // Act
        $result = $holder->withBackchannelClientNotificationEndpoint('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getBackchannelClientNotificationEndpoint());
    }
    /**
     * Asserts that withbackchannelClientNotificationEndpoint has access to the value object
     * from a string value, and getBackchannelClientNotificationEndpoint returns the primitive string.
     */
    public function testWithBackchannelClientNotificationEndpointFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientBackchannelClientNotificationEndpointAccessorUnitTest();

        // Act
        $result = $holder->withBackchannelClientNotificationEndpoint('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->backchannelClientNotificationEndpoint()->value());
    }
    public function testChangedBackchannelClientNotificationEndpoint(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientBackchannelClientNotificationEndpointAccessorUnitTest();
        $original = $holder->withBackchannelClientNotificationEndpoint('one');
        $same = $holder->withBackchannelClientNotificationEndpoint('one');
        $modified = $holder->withBackchannelClientNotificationEndpoint('other');

        // Act
        $unchanged = $holder->isBackchannelClientNotificationEndpointChanged();
        $withSame = $original->isBackchannelClientNotificationEndpointChanged($same);
        $withDiferent = $original->isBackchannelClientNotificationEndpointChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientBackchannelClientNotificationEndpointAccessorUnitTest
{
    use TrustedClientBackchannelClientNotificationEndpointAccessor;
}
